using CustomCodeFramework.Core.Results;using CustomCodeFramework.Cqrs.Commands;using CustomCodeFramework.Persistence.Abstractions;using Dhole.Content.Application.Abstractions.Auditing;using Dhole.Content.Application.Abstractions.Cache;using Dhole.Content.Application.Abstractions.Repositories;using Dhole.Content.Application.Auditing;using Dhole.Content.Domain.Shared;namespace Dhole.Content.Application.Navigation.SetNavigationMenuActive;public sealed class SetNavigationMenuActiveCommandHandler(INavigationMenuRepository repo,IContentAuditService audit,IContentCacheService cache,IUnitOfWork uow):ICommandHandler<SetNavigationMenuActiveCommand,Result>{public async Task<Result> HandleAsync(SetNavigationMenuActiveCommand c,CancellationToken ct=default){var x=await repo.GetByIdAsync(c.Id,ct);if(x is null||x.IsDeleted)return Result.Failure(ContentErrors.MenuNotFound);var before=ContentAuditSnapshots.From(x);x.SetActive(c.IsActive,c.ActorUserId);await audit.PublishAsync(new ContentAuditEvent(ContentAuditEventTypes.MenuUpdated,ContentAuditActions.StatusChanged,ContentAuditEntityTypes.NavigationMenu,x.Id,c.ActorUserId,Before:before,After:ContentAuditSnapshots.From(x)),ct);await uow.SaveChangesAsync(ct);await cache.RemoveMenuAsync(x.SiteKey,x.Location,ct);return Result.Success();}}
